// Enumerate marked 16-cores with one doubled pair. Canonical ordering of the meeting fives; not quotienting base automorphisms. e(H21)<=57 by the global pair bound. Marked degree FIVE star. Check all earlier common-neighborhood obstructions on the partially fixed 22 vertices.
#include <array>
#include <vector>
#include <unordered_set>
#include <algorithm>
#include <cstdio>
#include <iostream>
using namespace std;int pc(int s){return __builtin_popcount((unsigned)s);}int key(int e,array<int,5>a){sort(a.begin(),a.end());for(int x:a)e=e*9+x;return e;}
bool legal(int*g,int n){int d[22][22];for(int i=0;i<n;i++)for(int j=0;j<i;j++){d[i][j]=d[j][i]=pc(g[i]&g[j]);if(d[i][j]>4)return false;}for(int i=0;i<n;i++)for(int j=0;j<i;j++)if(d[i][j]>=3)for(int k=0;k<j;k++)if(d[i][k]>=3&&d[j][k]>=3){int s=g[i]&g[j]&g[k],m=pc(s);if(m>3)return false;if(m==3){int b[3];for(int z=0;z<3;z++){b[z]=__builtin_ctz(s);s&=s-1;}int a=(d[i][j]==4)+(d[i][k]==4)+(d[j][k]==4),c=(d[b[0]][b[1]]==4)+(d[b[0]][b[2]]==4)+(d[b[1]][b[2]]==4);if(a==3||c==3||a+c>3)return false;}}return true;}
int main(int ac,char**av){FILE*f=fopen(av[1],"r");if(!f)return 1;array<int,5>d;int e;unordered_set<int>marks;while(fscanf(f,"%d%d%d%d%d%d",&e,&d[0],&d[1],&d[2],&d[3],&d[4])==6)marks.insert(key(e,d));int h[16],i=-1;long long pre=0,post=0;while(cin>>h[0]){++i;for(int j=1;j<16;j++)cin>>h[j];if(!legal(h,16))continue;vector<int>ss;for(int s=31;s<65536;s++)if(pc(s)==5){bool ok=true;for(int u=s;u;u&=u-1)if(h[__builtin_ctz(u)]&s){ok=false;break;}if(ok)ss.push_back(s);}for(int j=0;j<ss.size();j++)for(int k=j+1;k<ss.size();k++){int b=ss[j],c=ss[k];if(pc(b&c)!=1)continue;int k1=0;for(int u=b;u;u&=u-1)k1+=pc(h[__builtin_ctz(u)]&c);if(k1<7||k1>13)continue;for(int a:ss){if(a&(b|c))continue;int n=0;for(int u=a;u;u&=u-1)d[n++]=8-pc(h[__builtin_ctz(u)]&(b|c));if(!marks.count(key(44+k1,d)))continue;int X=a|b|c,ee=0;for(int u=X;u;u&=u-1)ee+=pc(h[__builtin_ctz(u)]&X);ee=4+ee/2;if(ee>37)continue;pre++;int g[22]={};copy(h,h+16,g);int S[]={a,b,c};for(int t=0;t<3;t++){g[16+t]=S[t]|(7<<19);g[19+t]=7<<16;for(int u=S[t];u;u&=u-1)g[__builtin_ctz(u)]|=1<<(16+t);}if(!legal(g,22))continue;post++;printf("%d %d %d %d %d %d\n",i,a,b,c,ee,44+k1);}}}cerr<<pre<<' '<<post<<'\n';}
